<section class="vd-panel"><form class="vd-filter" method="get"><label>Search<input name="q" value="{{ request('q') }}" placeholder="Product or SKU"></label><button class="vd-button">Search</button></form><div class="vd-table-wrap"><table><thead><tr><th>Product / SKU</th><th>Current warehouse stock</th><th>Reserved for open orders</th><th>Available</th><th>Threshold</th><th>Status</th><th>Updated</th></tr></thead><tbody>@forelse($products as $p)@php($reserved=DB::table('batch_allocations')->join('order_items','order_items.id','=','batch_allocations.order_item_id')->join('orders','orders.id','=','order_items.order_id')->where('order_items.vendor_id',$vendor->id)->where('order_items.product_id',$p->id)->whereIn('orders.status',['Placed','Confirmed','Packing','Packed'])->sum(DB::raw('batch_allocations.quantity-batch_allocations.returned_quantity')))<tr><td>{{ $p->name }}<small>{{ $p->sku }}</small></td><td>{{ $p->stock }}</td><td>{{ $reserved }}</td><td>{{ $p->available_stock }}</td><td>{{ $p->low_stock_threshold }}</td><td><span class="vd-badge {{ !$p->available_stock?'danger':($p->available_stock<=$p->low_stock_threshold?'warning':'') }}">{{ !$p->available_stock?'Out of Stock':($p->available_stock<=$p->low_stock_threshold?'Low Stock':'In Stock') }}</span></td><td>{{ $p->updated_at->format('d M Y H:i') }}</td></tr>@empty<tr><td colspan="7">No products assigned to your store.</td></tr>@endforelse</tbody></table></div>{{ $products->links() }}<p class="vd-note">Checkout already deducts reserved goods from warehouse stock. The reserved column is informational; it is not subtracted again. Expired stock is excluded from Available.</p></section>
<section class="vd-panel"><h2>Request a stock receipt</h2><p>Submit delivered goods for admin inspection. Approval creates an Inward receipt and FIFO batch; a request alone does not change stock. For goods supplied against a purchase order, use the purchase-order workflow instead.</p><form method="post" action="{{ route('vendor.stock-request') }}">@csrf<input type="hidden" name="request_key" value="{{ old('request_key',(string)\Illuminate\Support\Str::uuid()) }}"><div class="vd-form-grid"><label>Product<select name="product_id" required><option value="">Select your product</option>@foreach(\App\Product::where('vendor_id',$vendor->id)->where('active',true)->get() as $p)<option value="{{ $p->id }}" {{ old('product_id')==$p->id?'selected':'' }}>{{ $p->name }} · {{ $p->sku }}</option>@endforeach</select></label>@foreach(['quantity'=>'Received quantity','batch_number'=>'Batch number','manufactured_on'=>'Manufacturing date','expires_on'=>'Expiry date','unit_cost'=>'Purchase cost per unit (₹)','invoice_number'=>'Supplier invoice number'] as $field=>$label)<label>{{ $label }}<input name="{{ $field }}" value="{{ old($field) }}" type="{{ in_array($field,['manufactured_on','expires_on'])?'date':(in_array($field,['quantity','unit_cost'])?'number':'text') }}" {{ in_array($field,['manufactured_on','expires_on'])?'':'required' }} @if($field==='quantity')min="1" max="1000000" step="1"@elseif($field==='unit_cost')min="0" max="10000000" step="0.01"@endif></label>@endforeach<label class="vd-span2">Reason / delivery notes<textarea name="reason" minlength="5" maxlength="1000" required>{{ old('reason') }}</textarea></label></div><button class="vd-button">Submit receipt request</button></form></section>
<section class="vd-panel"><h2>Receipt requests</h2><div class="vd-table-wrap"><table><thead><tr><th>Request</th><th>Batch</th><th>Quantity</th><th>Status</th><th>Admin notes</th><th>Inward reference</th></tr></thead><tbody>@forelse($requests as $row)<tr><td>#{{ $row->id }}</td><td>{{ $row->batch_number }}</td><td>{{ $row->quantity }}</td><td>{{ $row->status }}</td><td>{{ $row->review_notes?:'Awaiting review' }}</td><td>{{ $row->inward_id?\App\Inward::find($row->inward_id)->number:'—' }}</td></tr>@empty<tr><td colspan="6">No receipt requests yet.</td></tr>@endforelse</tbody></table></div></section>
